import { readFile, writeFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
const [kind, root, output] = process.argv.slice(2);
const hash = b => createHash('sha256').update(b).digest('hex');
async function files(dir) {
  const entries = await readdir(dir, {withFileTypes:true});
  const result=[];
  for(const e of entries) { const p=dir+'/'+e.name; if(e.isDirectory()) result.push(...await files(p)); else if(e.name.endsWith('.ts')) result.push(p); }
  return result;
}
async function sources() { const out={}; for (const p of (await files(root+'/src')).sort()) out[p.slice(root.length+1)]=hash(await readFile(p)); return out; }
const initialSources=await sources();
const requested=[];
const nativeFetch=globalThis.fetch;
globalThis.fetch=async function(input, init) {
  const url=typeof input==='string'? input:input instanceof URL?input.href:input.url;
  const row={url, credentials:init?.credentials ?? null, mode:init?.mode ?? null, startedAt:new Date().toISOString()}; requested.push(row);
  const t=performance.now();
  try { const response=await nativeFetch(input,init); Object.assign(row,{status:response.status,responseURL:response.url,milliseconds:performance.now()-t}); return response; }
  catch(error) { Object.assign(row,{error:String(error),milliseconds:performance.now()-t}); throw error; }
};
const {downloadWebsite}=await import(pathToFileURL(root+'/src/installation/import-website.ts').href);
const source='https://gchq.github.io/CyberChef/';
const input=kind==='before'?source:{url:source,resourceList:{kind:'url',url:'https://privacy-frames.github.io/apps/resource-lists/cyberchef.uris'}};
const startedAt=new Date().toISOString(); const start=performance.now();
const result={kind, input, sourceRevision:execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim(), sourceClean:execFileSync('git',['status','--porcelain','--untracked-files=no'],{cwd:root,encoding:'utf8'}).trim()==='',node:process.version,platform:process.platform,architecture:process.arch,browser:null, applicationExecuted:false, startedAt};
try { const installation=await downloadWebsite(input); Object.assign(result,{success:true,resourceCount:installation.resources.length,resourceBytes:installation.size,resources:installation.resources.map(r=>({url:r.url,size:r.bytes.byteLength,sha256:hash(Buffer.from(r.bytes))})),capture:installation.capture??null,preparation:installation.preparation??null}); }
catch(error) { Object.assign(result,{success:false,error:String(error),stack:error.stack}); }
Object.assign(result,{endedAt:new Date().toISOString(),milliseconds:performance.now()-start,requested,sourceFiles:initialSources,sourceFilesStable:JSON.stringify(initialSources)===JSON.stringify(await sources())});
await writeFile(output,JSON.stringify(result,null,2)+'\n');
process.stdout.write(JSON.stringify({kind,success:result.success,milliseconds:result.milliseconds,resourceCount:result.resourceCount,resourceBytes:result.resourceBytes,requests:requested.length,error:result.error})+'\n');
